### Clear Explanation

A **decorator** is a function that takes a function and returns a modified version of it.

```python
# This:
@my_decorator
def my_function():
    pass

# Is exactly the same as:
def my_function():
    pass
my_function = my_decorator(my_function)
```

**Why decorators?**

- Add behavior WITHOUT modifying the original function
- Cross-cutting concerns: logging, timing, auth, caching, retry
- Clean, reusable, composable

### Example 1 — Building a Decorator Step by Step

```python
import functools
import time

# Step 1: A decorator is a function that takes a function
def timer(func):
    # Step 2: Define a wrapper that adds behavior
    @functools.wraps(func)  # Preserves func's name, docstring, etc.
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)  # Call the original function
        end = time.perf_counter()
        print(f"{func.__name__} took {end - start:.4f} seconds")
        return result  # Return the original result
    # Step 3: Return the wrapper
    return wrapper

@timer
def slow_function(n):
    """This is a slow function."""
    total = sum(range(n))
    return total

result = slow_function(1_000_000)
# Output: slow_function took 0.0312 seconds

# functools.wraps preserves the original function's identity
print(slow_function.__name__)  # "slow_function" (not "wrapper")
print(slow_function.__doc__)   # "This is a slow function."
```

### Example 2 — Practical Decorators

```python
import functools
import time

# Retry decorator
def retry(max_attempts=3, delay=1):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts:
                        raise
                    print(f"Attempt {attempt} failed: {e}. Retrying...")
                    time.sleep(delay)
        return wrapper
    return decorator

# Cache/Memoize decorator
def memoize(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

# Logging decorator
def log_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        args_str = ", ".join([repr(a) for a in args] + [f"{k}={v!r}" for k, v in kwargs.items()])
        print(f"Calling {func.__name__}({args_str})")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned {result!r}")
        return result
    return wrapper

@log_calls
@memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(fibonacci(10))  # 55 (with logging and caching)
```

### Example 3 — Real-World Decorators

```python
import functools
from datetime import datetime

# Authentication decorator (like Flask/FastAPI)
def require_auth(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        # In real code: check request headers, JWT tokens, etc.
        user = kwargs.get("user")
        if not user or not user.get("authenticated"):
            raise PermissionError("Authentication required")
        return func(*args, **kwargs)
    return wrapper

# Rate limiting decorator
def rate_limit(max_calls, period):
    calls = []
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now = datetime.now()
            # Remove old calls outside the period
            while calls and (now - calls[0]).total_seconds() > period:
                calls.pop(0)
            if len(calls) >= max_calls:
                raise RuntimeError(f"Rate limit exceeded: {max_calls} calls per {period}s")
            calls.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Validation decorator
def validate_types(**type_hints):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for param_name, expected_type in type_hints.items():
                if param_name in kwargs:
                    value = kwargs[param_name]
                    if not isinstance(value, expected_type):
                        raise TypeError(f"{param_name} must be {expected_type.__name__}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

@require_auth
def get_secret_data(user=None):
    return "Top secret!"

@rate_limit(max_calls=5, period=60)
def api_call():
    return "API response"
```

### 5 Exercises

1. Create a `@timer` decorator that prints execution time.
2. Build a `@retry(max_attempts=3)` decorator with exponential backoff.
3. Implement `@cache` decorator (like `functools.lru_cache`).
4. Create a `@deprecated(message)` decorator that prints a warning.
5. Build a `@validate_args` decorator that checks argument types.

### 7 Interview Questions

**Q1: What is a decorator?**

> **A:** A function that takes a function as input and returns a new function with added behavior. It wraps the original function without modifying it. `@decorator` syntax is syntactic sugar for `func = decorator(func)`.

**Q2: Why use `functools.wraps`?**

> **A:** Without it, the decorated function loses its `__name__`, `__doc__`, and `__module__`. `@functools.wraps(func)` copies these attributes from the original function to the wrapper.

**Q3: How do decorators with arguments work?**

> **A:** Three layers: outer function takes arguments, returns a decorator. The decorator takes the function, returns a wrapper. `@retry(3)` → `retry(3)` returns `decorator` → `decorator(func)` returns `wrapper`.

**Q4: Can you stack multiple decorators?**

> **A:** Yes. `@a @b @c def func():` is equivalent to `func = a(b(c(func)))`. Bottom decorator is applied first. Order matters!

**Q5: What is the difference between `@decorator` and `@decorator()`?**

> **A:** `@decorator` — decorator is the function itself (takes func). `@decorator()` — decorator() is called first (returns the actual decorator). Parentheses mean it's a decorator factory.

**Q6: Can you decorate a class?**

> **A:** Yes. Class decorators take a class and return a modified class. `@dataclass` is a class decorator. You can also use classes as decorators (with `__call__`).

**Q7: Name some built-in decorators.**

> **A:** `@property`, `@classmethod`, `@staticmethod`, `@functools.lru_cache`, `@functools.wraps`, `@functools.total_ordering`, `@abc.abstractmethod`, `@dataclasses.dataclass`.

### 8 Scenario-Based Interview Questions

**S1:** You need to add logging to 50 existing functions. How?

> **A:** Create a `@log_calls` decorator and apply it. Don't modify the 50 functions' code. The decorator adds logging before/after each call. One change, applied everywhere.

**S2:** A decorator needs access to the class instance (`self`). How?

> **A:** The wrapper receives `self` as the first argument: `def wrapper(self, *args, **kwargs):`. Or use a class as the descriptor-aware decorator.

**S3:** Your decorator breaks when applied to async functions. Fix?

> **A:** Check if the function is a coroutine and use `await`: `if asyncio.iscoroutinefunction(func): async def wrapper(*args, **kwargs): return await func(*args, **kwargs)`.

**S4:** You want to make a decorator optional (enabled/disabled by config). How?

> **A:** `def optional_decorator(func): if not CONFIG['enabled']: return func; ...`. Or make the decorator a no-op: return the original function unmodified.

**S5:** A decorated function's signature is lost (all shows as `*args, **kwargs`). Fix?

> **A:** Use `functools.wraps` (preserves name/doc). For full signature preservation, use the `inspect` module or the `decorator` library which preserves the full signature.

**S6:** You need a decorator that works both with and without arguments: `@deco` and `@deco(arg)`.

> **A:** Check if the first argument is callable: `def deco(func=None, *, arg=default): if func is None: return partial(deco, arg=arg); ...`.

**S7:** Your caching decorator doesn't work with unhashable arguments (lists, dicts). Fix?

> **A:** Convert unhashable args to hashable: use `str(args)` or `json.dumps(args, sort_keys=True)` as the cache key. Or use `functools.lru_cache` which requires hashable args.

**S8:** You need to apply a decorator to all methods in a class. How?

> **A:** Create a class decorator: `def decorate_all(cls): for name, method in inspect.getmembers(cls, inspect.isfunction): setattr(cls, name, decorator(method)); return cls`.

### Example 1 — Three-Layer Pattern

```python
import functools

def repeat(n=2):
    """Decorator factory — takes arguments, returns decorator."""
    def decorator(func):
        """Actual decorator — takes function, returns wrapper."""
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            """Wrapper — adds behavior around original function."""
            results = []
            for _ in range(n):
                results.append(func(*args, **kwargs))
            return results
        return wrapper
    return decorator

@repeat(n=3)
def greet(name):
    return f"Hello, {name}!"

print(greet("Alice"))  # ['Hello, Alice!', 'Hello, Alice!', 'Hello, Alice!']

# What happens:
# 1. repeat(n=3) is called → returns decorator
# 2. decorator(greet) is called → returns wrapper
# 3. greet = wrapper
```

### Example 2 — Decorator That Works With and Without Arguments

```python
import functools

def smart_decorator(func=None, *, prefix="LOG"):
    """Works as @smart_decorator and @smart_decorator(prefix='DEBUG')."""
    if func is None:
        # Called with arguments: @smart_decorator(prefix='DEBUG')
        return functools.partial(smart_decorator, prefix=prefix)

    # Called without arguments: @smart_decorator
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"[{prefix}] Calling {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

@smart_decorator
def func1():
    return "hello"

@smart_decorator(prefix="DEBUG")
def func2():
    return "world"

func1()  # [LOG] Calling func1
func2()  # [DEBUG] Calling func2
```

### Quick Reference

```python
import functools

# @property — attribute-like access
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def area(self):
        return 3.14159 * self._radius ** 2

# @staticmethod / @classmethod
class MyClass:
    @staticmethod
    def utility(): pass

    @classmethod
    def factory(cls): return cls()

# @functools.lru_cache — automatic memoization
@functools.lru_cache(maxsize=128)
def expensive_computation(n):
    return sum(i**2 for i in range(n))

# @functools.total_ordering — generate comparison methods
@functools.total_ordering
class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade

    def __eq__(self, other):
        return self.grade == other.grade

    def __lt__(self, other):
        return self.grade < other.grade
    # Now <=, >, >= are auto-generated!

# @functools.cached_property (Python 3.8+) — compute once, store as attribute
class DataModel:
    @functools.cached_property
    def processed_data(self):
        print("Computing...")
        return expensive_operation()
```
